import json

# Let me check meeting_chats for all products related to MRR
import os
products_dir = 'DATA/products'

for fname in sorted(os.listdir(products_dir)):
    if not fname.endswith('.json'):
        continue
    with open(os.path.join(products_dir, fname)) as f:
        data = json.load(f)

    # Find MRR-related meeting chats
    if 'meeting_chats' in data:
        for c in data['meeting_chats']:
            if 'market_research' in c.get('text', '').lower():
                print(f'{fname} - {c["id"]}: {c["text"][:200]}')
EOF

