import json

# Check if any documents have "authors" field
with open('DATA/products/CoachForce.json') as f:
    data = json.load(f)

for d in data['documents']:
    if 'authors' in d:
        print(f'{d["id"]}: authors = {d["authors"]}')
    # Also check content for co-author mentions
    content = d['content']
    if 'co-author' in content.lower() or 'contributor' in content.lower():
        for line in content.split('\n'):
            if 'co-author' in line.lower() or 'contributor' in line.lower():
                print(f'{d["id"]}: {line}')
EOF

